window.docContents[98].resolve({"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Membership":{"contents":"def member (n : Nat) (l : NatList) : Bool := solution!(\n  match l with\n  | [] => false\n  | h :: t => bif n == h then true else member n t)\n\ntheorem member_nil (n : Nat) : member n [] = false := solution!(by rfl)\n\ntheorem member_cons_same (n₁ n₂ : Nat) (t : NatList) (h : (n₁ == n₂) = true) :\n    member n₁ (n₂ :: t) = true := by\n  solution!\n    rw [member, h, cond_true]\n\ntheorem member_cons_diff (n₁ n₂ : Nat) (t : NatList) (h : (n₁ == n₂) = false) :\n    member n₁ (n₂ :: t) = member n₁ t := by\n  solution!\n    rw [member, h, cond_false]\n\nexample : member 1 [1] = true := by\n  rw [member_cons_same _ _ _ rfl]\n\nexample : member 2 [1] = false := solution!(by rfl)\ntheorem test_member1 : member 1 [1, 4, 1] = true := solution!(by rfl)\n\ntheorem test_member2 : member 2 [1, 4, 1] = false := solution!(by rfl)\n\n\n","context":"Logical Foundations\u0009Lists: Working with Structured Data\u0009Lists of Numbers","header":"5.2.5. Membership","id":"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Membership"}});